#!/bin/bash
# Generated by image-composer-tool. Runs the OEP Installer (openedge-cli) on
# first boot for the image's modules, as the image template's user. The
# provisioning unit runs this script again on each boot until it succeeds, for
# example after openedge-cli reboots the system to finish an installation step.
#
# Arguments: the modules and arguments for "openedge-cli install".
# Environment: OEP_INSTALLER_USER (the user), OEP_INSTALLER_CLI (the CLI file).
set -euo pipefail

user="${OEP_INSTALLER_USER:?}"
cli="${OEP_INSTALLER_CLI:?}"
sudoers=/etc/sudoers.d/90-ict-oep-installer

# openedge-cli runs its privileged steps through "sudo -n". Allow that only
# while this script runs; a tmpfiles.d rule also removes the grant at boot.
cleanup() { rm -f "$sudoers" "$sudoers.tmp"; }
trap cleanup EXIT
trap 'exit 143' TERM INT HUP
printf '%s ALL=(ALL) NOPASSWD: ALL\n' "$user" >"$sudoers.tmp"
chmod 0440 "$sudoers.tmp"
visudo -cqf "$sudoers.tmp"
mv "$sudoers.tmp" "$sudoers"

home="$(getent passwd "$user" | cut -d: -f6)"
cd "$home"
# Each step runs in the background so a stop signal reaches the traps at once
# instead of after the step exits; wait returns the step's exit status.
as_user() {
	runuser -u "$user" -- env HOME="$home" USER="$user" LOGNAME="$user" "$@" &
	wait "$!"
}

# setup saves the CLI as ~/.local/bin/openedge-cli and adds bash completion.
as_user bash "$cli" setup
as_user "$home/.local/bin/openedge-cli" install "$@"
